function localSave(message){try{localStorage.setItem(key,JSON.stringify(db));if(message){db.activity.unshift({text:message,date:new Date().toISOString()});db.activity=db.activity.slice(0,35);localStorage.setItem(key,JSON.stringify(db));toast(message)}}catch{toast('Storage is full or unavailable. Export a backup before leaving.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function go(p){if(p===page){render();return}location.hash=p}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';filter=page==='projects'?'Active':'All';query='';render()});
function badge(v){const color=/Done|Delivered|Active|Paid|Completed|On track/.test(v)?'green':/Hold|High|Overdue|Blacklisted/.test(v)?'red':/Review/.test(v)?'purple':/Low|Planning|Upcoming/.test(v)?'blue':'gray';return `<span class="badge ${color}">${esc(v)}</span>`}
function legacyAvatar(name='Mineth',i=0){return `<span class="avatar" title="${esc(name)}" style="background:linear-gradient(140deg,${['#a56c48,#493941','#557c73,#303c40','#8b6678,#413650'][i%3]})">${esc(initials(name))}</span>`}
const avatars=()=>`<div class="avatars">${db.users.slice(0,3).map((u,i)=>avatar(u.name,i)).join('')}</div>`;
function progress(v){v=Math.min(100,Math.max(0,+v||0));return `<div class="progress"><span style="width:${v}%"></span></div>`}
function spark(color='#ff772b'){return `<svg class="spark" viewBox="0 0 120 40"><path d="M1 36 12 25 25 28 36 20 47 24 62 11 75 16 86 9 100 13 118 2" stroke="${color}" stroke-width="1.5" fill="none"/><path d="M1 36 12 25 25 28 36 20 47 24 62 11 75 16 86 9 100 13 118 2V40H1Z" fill="${color}" opacity=".05"/></svg>`}
function stat(title,value,ico,color='orange',note=''){return `<div class="stat"><div class="stat-head"><span class="tile ${color}">${icon(ico)}</span><div><small>${esc(title)}</small><strong>${esc(value)}</strong></div></div>${note?`<div class="stat-footer">${esc(note)}</div>`:''}</div>`}
function panel(title,ico,body,action='',sub=''){return `<section class="panel"><div class="panel-head"><div class="panel-title"><span class="tile">${icon(ico)}</span><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div></div>${action}</div>${body}</section>`}
const navbutton=(title,p)=>`<button data-go="${p}">${title} ${icon('arrow')}</button>`;
function hero(title,sub,button='',home=false){return `<section class="hero ${home?'homehero':''}"><div>${home?`<div class="eyebrow">Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(db.settings.owner.split(' ')[0])}! <span style="color:#ffb941">✦</span></div>`:''}<h1>${title}</h1><p>${sub}</p>${home?`<button class="primary" data-go="projects">View Projects ${icon('arrow')}</button>`:''}</div><div class="hero-actions">${button}</div></section>`}
function heading(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><div class="muted">${sub}</div></div>${action}</div>`}
const addBtn=(kind,label)=>`<button class="primary" data-add="${kind}">${icon('plus')}${label}</button>`;
const revenue=()=>db.transactions.filter(t=>t.type==='Income').reduce((a,t)=>a+Number(t.amount),0),expenses=()=>db.transactions.filter(t=>t.type==='Expense').reduce((a,t)=>a+Number(t.amount),0),totalInvoice=i=>i.items.reduce((s,x)=>s+(+x.qty)*(+x.rate),0)*(1+(+i.tax||0)/100),outstanding=()=>db.invoices.filter(i=>i.status==='Sent'||i.status==='Overdue').reduce((a,i)=>a+totalInvoice(i),0);
function legacyChart(period=6){const months=Array.from({length:period},(_,i)=>{let d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(period-1-i));return {key:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),label:d.toLocaleDateString('en',{month:'short'})}});let a=months.map(m=>db.transactions.filter(t=>t.date?.startsWith(m.key)&&t.type==='Income').reduce((s,t)=>s+ +t.amount,0)),b=months.map(m=>db.transactions.filter(t=>t.date?.startsWith(m.key)&&t.type==='Expense').reduce((s,t)=>s+ +t.amount,0));let max=Math.max(...a,...b,1)*1.15;const points=v=>v.map((n,i)=>`${40+i*420/(period-1)},${170-n/max*140}`).join(' ');return `<div class="legend"><span><i class="dot"></i>Revenue</span><span><i class="dot" style="background:#bfc7ce"></i>Expenses</span></div><svg class="chart" viewBox="0 0 480 202" role="img" aria-label="Monthly revenue and expenses chart">${[0,1,2,3].map(i=>`<line class="gridline" x1="40" y1="${170-i*46}" x2="460" y2="${170-i*46}"/><text x="0" y="${174-i*46}">${Math.round(max*i/3/1000)}k</text>`).join('')}<defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ff681f" stop-opacity=".28"/><stop offset="1" stop-color="#ff681f" stop-opacity="0"/></linearGradient></defs><polygon points="40,170 ${points(a)} 460,170" fill="url(#area)"/><polyline points="${points(a)}" fill="none" stroke="#ff771f" stroke-width="2.7"/><polyline points="${points(b)}" fill="none" stroke="#b9c3ca" stroke-width="2"/>${months.map((m,i)=>`<text x="${40+i*420/(period-1)}" y="197" text-anchor="middle">${m.label}</text><circle cx="${40+i*420/(period-1)}" cy="${170-a[i]/max*140}" r="3" fill="#ff7723"/>`).join('')}</svg>`}
function health(){const done=db.tasks.filter(t=>t.status==='Done').length,score=db.tasks.length?Math.round(done/db.tasks.length*100):0;return `<div class="health"><div class="ring" style="background:conic-gradient(var(--accent) ${score}%,#313636 ${score}%)"><div class="ring-inner"><strong>${score}%</strong><small>Tasks completed</small><small style="color:#6dce91">${done} of ${db.tasks.length}</small></div></div><div class="health-list"><div>Active projects ${badge(String(db.projects.filter(p=>!['Delivered','Archived','Portfolio Queue','On Hold'].includes(p.status)).length))}</div><div>Open tasks ${badge(String(db.tasks.length-done))}</div><div>Team members ${badge(String(db.users.length))}</div><div>Overdue invoices ${badge(String(db.invoices.filter(i=>i.status==='Overdue').length))}</div></div></div>`}
function meetingRows(){return db.meetings.filter(m=>m.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,4).map(m=>`<div class="row"><span class="accent-line"></span><time>${esc(m.time)}</time><div class="row-main"><b>${esc(m.title)}</b><small>${date(m.date)}</small></div>${badge(m.type)}</div>`).join('')||'<div class="empty">No upcoming meetings</div>'}
function taskRows(){return db.tasks.filter(t=>t.status!=='Done').slice(0,5).map(t=>`<div class="row"><span class="monogram">${icon('tasks')}</span><div class="row-main"><b>${esc(t.title)}</b><small>${esc(db.projects.find(p=>p.id===t.project)?.name||'Studio')}</small></div><div style="width:50px">${progress(t.progress)}</div><button class="iconbtn" data-edit="tasks:${t.id}" aria-label="Edit ${esc(t.title)}">${icon('chevron')}</button></div>`).join('')||'<div class="empty">All caught up.</div>'}
function home(){return hero('Your studio<br>is in <em>motion.</em>',`${db.projects.filter(p=>['In Progress','In Review','Planning'].includes(p.status)).length} active projects &nbsp; • &nbsp; ${db.meetings.filter(m=>m.date===today()).length} meetings today`,'',true)+`<div class="stats">${stat('Revenue',money(revenue()),'money','green')}${stat('Net Profit',money(revenue()-expenses()),'chart')}${stat('Outstanding',money(outstanding()),'clock','red','Sent & overdue invoices')}${stat('Active Projects',db.projects.filter(p=>['In Progress','In Review','Planning'].includes(p.status)).length,'layers','blue')}</div><div class="grid three">${panel('Project Activity','chart',chart(),navbutton('Finance','finance'),'')}${panel('Upcoming Meetings','meetings',meetingRows(),navbutton('See all','meetings'),'')}${panel('Task Queue','tasks',taskRows(),navbutton('View all','tasks'),'')}</div><div class="grid three">${panel('Revenue & Cashflow','trend',chart(4))}${panel('Studio Pulse','star',health(),'','')}${panel('Recent Activity','clock',db.activity.slice(0,5).map(a=>`<div class="row"><span class="dot"></span><div class="row-main"><b>${esc(a.text)}</b><small>${date(a.date)}</small></div></div>`).join(''))}</div>`}
function projects(){const list=db.projects.filter(p=>(filter==='All'||filter==='Active'&&!['Delivered','Archived','Portfolio Queue','On Hold'].includes(p.status)||p.status===filter)&&(!query||(p.name+' '+p.client).toLowerCase().includes(query.toLowerCase())));return heading('Projects','Plan, track, and deliver exceptional work.',addBtn('projects','New Project'))+`<div class="tabs">${['Active','Delivered','Portfolio Queue','Archived','All'].map(t=>`<button data-filter="${t}" class="${filter===t?'selected':''}">${t} (${db.projects.filter(p=>t==='All'||t==='Active'&&!['Delivered','Archived','Portfolio Queue','On Hold'].includes(p.status)||p.status===t).length})</button>`).join('')}</div><div class="stats">${stat('Total Projects',db.projects.length,'chart')}${stat('Active',db.projects.filter(p=>['Planning','In Progress','In Review'].includes(p.status)).length,'tasks','green')}${stat('Delivered',db.projects.filter(p=>p.status==='Delivered').length,'trend','green')}${stat('On Hold',db.projects.filter(p=>p.status==='On Hold').length,'clock','red')}</div><div class="toolbar">${search('Search projects...')}<select id="project-sort" aria-label="Sort projects"><option value="recent">Sort by: Recent</option><option value="date">Due date</option><option value="name">Name</option></select></div><div class="table-wrap"><table><thead><tr><th>Project ↕</th><th>Client</th><th>Status</th><th>Progress</th><th>Due Date</th><th>Team</th><th></th></tr></thead><tbody id="project-rows">${projectRows(list)}</tbody></table>${!list.length?'<div class="empty">No projects here. Create your next project.</div>':''}</div>`}
function projectRows(list){return list.map(p=>`<tr><td><div class="project-name"><span class="monogram">${esc(initials(p.name))}</span>${esc(p.name)}</div></td><td>${esc(p.client)}</td><td>${badge(p.status)}</td><td><div class="progress-cell">${p.progress}% ${progress(p.progress)}</div></td><td>${date(p.due)}</td><td>${avatars()}</td><td><button class="iconbtn" data-edit="projects:${p.id}" aria-label="Edit ${esc(p.name)}">${icon('edit')}</button></td></tr>`).join('')}
function search(placeholder){return `<div class="searchbox">${icon('search')}<input id="page-search" placeholder="${placeholder}" value="${esc(query)}" aria-label="${placeholder}"></div>`}
function tasks(){let list=db.tasks.filter(t=>(filter==='All'||filter==='Mine'&&isMyTask(t)||filter==='Overdue'&&t.due<today()&&t.status!=='Done'||filter==='Done'&&t.status==='Done')&&(!query||t.title.toLowerCase().includes(query.toLowerCase())));return hero('Tasks','Manage studio execution across projects.',addBtn('tasks','New Task'))+`<div class="toolbar"><div class="tabs">${['All','Mine','Overdue','Done'].map(x=>`<button data-filter="${x}" class="${filter===x?'selected':''}">${x}</button>`).join('')}</div>${search('Find a task...')}</div><div class="stats">${stat('Total Tasks',db.tasks.length,'chart')}${stat('Due Today',db.tasks.filter(t=>t.due===today()&&t.status!=='Done').length,'meetings','red')}${stat('In Progress',db.tasks.filter(t=>t.status==='In Progress').length,'clock','blue')}${stat('Completed',db.tasks.filter(t=>t.status==='Done').length,'tasks','green')}</div><div class="kanban">${['Backlog','In Progress','Review','Done'].map(status=>`<section class="column" data-drop="${status}"><div class="column-head"><span>${status} <small>(${list.filter(t=>t.status===status).length})</small></span><button data-add="tasks" data-status="${status}" aria-label="Add task to ${status}">${icon('plus')}</button></div>${list.filter(t=>t.status===status).map(t=>`<article class="task-card" draggable="true" data-task="${t.id}"><div class="task-top"><h3>${esc(t.title)}</h3>${badge(t.priority)}</div><div class="section-note">${esc(db.projects.find(p=>p.id===t.project)?.name||'Studio')}</div><p>${esc(t.description==='Keep the next step clear and move the project forward.'?'':t.description)}</p><div class="progress-cell"><small>${t.progress}%</small>${progress(t.progress)}</div><div class="task-bottom"><span>${date(t.due)}</span>${avatar(t.assignee)}</div><div class="task-bottom"><select aria-label="Status for ${esc(t.title)}" data-task-status="${t.id}">${options(['Backlog','In Progress','Review','Done'],t.status)}</select><button class="iconbtn" data-edit="tasks:${t.id}" aria-label="Edit ${esc(t.title)}">${icon('edit')}</button></div></article>`).join('')||'<div class="empty">Drop tasks here</div>'}</section>`).join('')}</div><p class="section-note">Drag cards between columns, or use each card’s status menu.</p>`}
function clients(){const list=db.clients.filter(c=>(filter==='All'||c.status===filter)&&(!query||(c.name+c.contact+c.email).toLowerCase().includes(query.toLowerCase())));const c=list.find(x=>x.id===clientSelected)||list[0];return hero('Clients','Strong relationships. Exceptional work.',addBtn('clients','Add Client'))+`<div class="stats">${stat('Total Clients',db.clients.length,'clients')}${stat('Active Clients',db.clients.filter(c=>c.status==='Active').length,'users','green')}${stat('Inactive',db.clients.filter(c=>c.status==='Inactive').length,'clock','blue')}${stat('Outstanding Receivables',money(outstanding()),'money')}</div><div class="toolbar"><div class="tabs">${['All','Active','Inactive','Blacklisted'].map(x=>`<button data-filter="${x}" class="${filter===x?'selected':''}">${x}</button>`).join('')}</div>${search('Search clients by name or contact...')}</div><div class="client-layout"><div class="table-wrap"><table><thead><tr><th>Client</th><th>Contact</th><th>Projects</th><th>Status</th><th></th></tr></thead><tbody>${list.map(x=>`<tr class="clickable ${c?.id===x.id?'selected-row':''}" data-client="${x.id}"><td><div class="project-name"><span class="monogram">${esc(initials(x.name))}</span><div>${esc(x.name)}<span class="sub">${esc(x.email)}</span></div></div></td><td>${esc(x.contact)}</td><td>${db.projects.filter(p=>p.client===x.name).length}</td><td>${badge(x.status)}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">No matching clients</div>':''}</div>${c?`<section class="panel detail"><div class="detail-head"><span class="monogram">${esc(initials(c.name))}</span><div><strong>${esc(c.name)}</strong><p class="section-note">${esc(c.website)}</p></div>${badge(c.status)}</div><dl><dt>Primary Contact</dt><dd>${esc(c.contact)}</dd><dt>Email</dt><dd><a href="mailto:${esc(c.email)}">${esc(c.email)}</a></dd><dt>Phone</dt><dd>${esc(c.phone)||'Not provided'}</dd><dt>Industry</dt><dd>${esc(c.industry)}</dd><dt>Location</dt><dd>${esc(c.location)}</dd></dl><h3 style="font-size:13px">Notes</h3><p class="section-note">${esc(c.notes)||'Add notes about your relationship and next steps.'}</p><div class="mini-stats"><div><strong>${db.projects.filter(p=>p.client===c.name).length}</strong><small>Projects</small></div><div style="grid-column:span 2"><strong>${money(db.invoices.filter(i=>i.client===c.name&&['Sent','Overdue'].includes(i.status)).reduce((s,i)=>s+totalInvoice(i),0))}</strong><small>Outstanding</small></div></div><button class="primary wide" style="margin-top:22px" data-edit="clients:${c.id}">Edit Client ${icon('arrow')}</button></section>`:''}</div>`}
const meetingExample=()=>({type:'chakra-meeting.v1',title:'Client Review — Nova Labs',date:offset(2)+'T14:00:00',project:'Nova Brand Identity',attendees:[{name:'Mineth Banula'},{name:'Kaweesha'}],summary:'Reviewed design direction and finalized next steps.',action_items:[{task:'Send updated mockups',assignee:'Mineth',due_date:offset(4)}],tags:['design','client','review']});
function meetings(){return hero('Meetings','Capture notes, tasks, and calendar events.',`<button data-action="calendar">${icon('download')}Export Calendar</button>${addBtn('meetings','New Meeting')}`)+`<div class="tabs">${['Upcoming','Import'].map(t=>`<button data-meeting-tab="${t}" class="${meetingTab===t?'selected':''}">${t==='Import'?'ChatGPT Import':t}</button>`).join('')}</div>${meetingTab==='Import'?`<div class="grid equal">${panel('Paste structured meeting output','upload',`<textarea id="meeting-json" class="code" aria-label="Meeting JSON" spellcheck="false">${esc(JSON.stringify(meetingExample(),null,2))}</textarea><button data-action="parse-meeting" class="primary wide" style="margin-top:13px">Parse & Preview ${icon('arrow')}</button>`,`<button data-action="format-guide">Format Guide</button>`,'Import notes using the chakra-meeting.v1 format.')}${panel('Preview','meetings',`<div id="meeting-preview"><div class="empty">Paste meeting JSON and select Parse & Preview.<br><br>Action items can become tasks when you save.</div></div>`)}</div>`:`<div class="grid equal">${panel('Upcoming Meetings','meetings',meetingRows())}${panel('Meeting notes','bills','<p class="section-note">Create a meeting manually, or import structured notes from ChatGPT. Saved action items become tasks linked to the selected project. Export an .ics file to add meetings to your calendar.</p>')}</div>`}<div class="grid">${panel('All Meetings','clock',`<div class="table-wrap"><table><thead><tr><th>Title</th><th>Project</th><th>Date & Time</th><th>Action Items</th><th></th></tr></thead><tbody>${db.meetings.map(m=>`<tr><td>${esc(m.title)}</td><td>${esc(db.projects.find(p=>p.id===m.project)?.name||'Studio')}</td><td>${date(m.date)} · ${esc(m.time)}</td><td>${m.action_items?.length||0}</td><td><button class="iconbtn" data-edit="meetings:${m.id}" aria-label="Edit ${esc(m.title)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`)}</div>`}
function subscriptions(){const active=db.subscriptions.filter(s=>s.status==='Active'),monthly=active.reduce((s,x)=>s+ +x.amount,0),list=db.subscriptions.filter(s=>(filter==='All'||s.status===filter)&&s.name.toLowerCase().includes(query.toLowerCase()));return hero('Subscriptions','Manage recurring tools, renewals, FX rates, and reminders.',addBtn('subscriptions','Add Subscription'))+`<div class="stats">${stat('Monthly Recurring',money(monthly,'USD'),'finance','green','≈ '+money(monthly*db.settings.fx,'LKR'))}${stat('Annualized',money(monthly*12,'USD'),'chart','orange','12 × monthly cost')}${stat('Active Subscriptions',active.length,'layers','blue')}${stat('Renewing in 7 days',active.filter(s=>s.renewal>=today()&&s.renewal<=offset(7)).length,'bell','red')}</div><div class="toolbar"><h3>All Subscriptions (${list.length})</h3>${search('Search subscriptions...')}<select id="status-filter" aria-label="Subscription status">${options(['All','Active','Paused'],filter)}</select></div><div class="table-wrap"><table><thead><tr><th>Tool / Service</th><th>Website</th><th>Amount (USD)</th><th>Amount (LKR)</th><th>Renewal Date</th><th>Reminder</th><th>Auto-Renew</th><th>Status</th><th></th></tr></thead><tbody>${list.map((s,i)=>`<tr><td><div class="project-name">${faviconMarkup(s)}${esc(s.name)}</div></td><td><a href="https://${esc(s.website.replace(/^https?:\/\//,''))}" target="_blank" rel="noopener noreferrer">${esc(s.website)}</a></td><td>${money(s.amount,'USD')}</td><td>${money(s.amount*db.settings.fx,'LKR')}</td><td>${date(s.renewal)}</td><td>${s.reminder} days before</td><td><button class="switch ${s.auto?'on':''}" role="switch" aria-checked="${s.auto}" aria-label="Track auto-renew for ${esc(s.name)}" data-toggle-sub="${s.id}"></button></td><td>${badge(s.status)}</td><td><button class="iconbtn" data-edit="subscriptions:${s.id}" aria-label="Edit ${esc(s.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div><div class="grid equal">${panel('Upcoming Renewals','clock',active.sort((a,b)=>a.renewal.localeCompare(b.renewal)).slice(0,3).map(s=>`<div class="row">${faviconMarkup(s)}<div class="row-main"><b>${esc(s.name)}</b><small>${money(s.amount,'USD')} · ${date(s.renewal)}</small></div><button data-edit="subscriptions:${s.id}">Manage</button></div>`).join(''))}${panel('Reminder Center','bell',`<p class="section-note">Renewal reminders appear here while the app is open. Auto-renew tracks your preference; it does not change your provider’s billing.</p>${active.filter(s=>s.renewal<=offset(s.reminder)&&s.renewal>=today()).map(s=>`<div class="row"><span class="tile">${icon('bell')}</span><div class="row-main"><b>${esc(s.name)} renews soon</b><small>${date(s.renewal)} · ${money(s.amount,'USD')}</small></div></div>`).join('')||'<div class="empty">No reminders due yet.</div>'}`)}</div>`}
function expenseGradient(){const cats=[...new Set(db.transactions.filter(t=>t.type==='Expense').map(t=>t.category))],colors=['#ff7025','#e74d10','#ab491c','#777','#a6aba5'];let n=0;return expenses()?'conic-gradient('+cats.map((c,i)=>{let start=n;n+=db.transactions.filter(t=>t.type==='Expense'&&t.category===c).reduce((a,t)=>a+ +t.amount,0)/expenses()*100;return colors[i%colors.length]+' '+start+'% '+n+'%'}).join(',')+')':'#333'}
function finance(){const categories=[...new Set(db.transactions.filter(t=>t.type==='Expense').map(t=>t.category))];return hero('Finance & <em>Analytics</em>','Track revenue, expenses, and studio performance.',addBtn('transactions','Add Transaction'))+`<div class="stats">${stat('Total Revenue',money(revenue()),'money','green')}${stat('Total Expenses',money(expenses()),'chart','red')}${stat('Net Profit',money(revenue()-expenses()),'trend','green')}${stat('Outstanding',money(outstanding()),'clock')}</div><div class="grid two">${panel('Revenue & Expenses','chart',chart(financePeriod==='3M'?3:6),`<select id="finance-period" aria-label="Chart period">${options(['6M','3M'],financePeriod)}</select>`)}${panel('Expense Breakdown','finance',`<div class="health"><div class="ring" style="background:${expenseGradient()}"><div class="ring-inner"><strong style="font-size:20px">${money(expenses())}</strong><small>Total expenses</small></div></div><div class="health-list">${categories.map(c=>`<div><span>${esc(c)}</span><b>${expenses()?Math.round(db.transactions.filter(t=>t.type==='Expense'&&t.category===c).reduce((s,t)=>s+ +t.amount,0)/expenses()*100):0}%</b></div>`).join('')}</div></div>`)}</div><div class="grid">${panel('Transactions','bills',`<div class="table-wrap"><table><thead><tr><th>Description</th><th>Category</th><th>Date</th><th>Type</th><th>Amount</th><th></th></tr></thead><tbody>${[...db.transactions].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${esc(t.title)}</td><td>${esc(t.category)}</td><td>${date(t.date)}</td><td>${badge(t.type)}</td><td style="color:${t.type==='Income'?'#50d787':'#ff9a72'}">${t.type==='Income'?'+':'−'}${money(t.amount)}</td><td><button class="iconbtn" data-edit="transactions:${t.id}" aria-label="Edit ${esc(t.title)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`,`<button data-action="export-transactions">${icon('download')}CSV</button>`)}</div>`}
function bills(){return hero('Bills & Invoices','Professional invoices. Clear payment tracking.',`<button class="primary" data-action="new-invoice">${icon('plus')}Create Invoice</button>`)+`<div class="stats">${stat('Invoices',db.invoices.length,'bills')}${stat('Paid',money(db.invoices.filter(i=>i.status==='Paid').reduce((s,i)=>s+totalInvoice(i),0)),'tasks','green')}${stat('Outstanding',money(outstanding()),'clock','red')}${stat('Drafts',db.invoices.filter(i=>i.status==='Draft').length,'edit','blue')}</div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Client</th><th>Issued</th><th>Due Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${db.invoices.map(i=>`<tr><td>${esc(i.number)}</td><td>${esc(i.client)}</td><td>${date(i.issued)}</td><td>${date(i.due)}</td><td>${money(totalInvoice(i))}</td><td><select aria-label="Status for invoice ${esc(i.number)}" data-invoice-status="${i.id}">${options(['Draft','Sent','Paid','Overdue'],i.status)}</select></td><td><button data-open-invoice="${i.id}">${icon('edit')}Open</button></td></tr>`).join('')}</tbody></table></div><p class="section-note">Invoice statuses are tracked locally. Sending and payment collection are managed outside this app.</p>`}
function invoiceEditor(){if(!invoice)invoice={id:id(),number:db.settings.prefix+new Date().getFullYear()+'-'+String(db.invoices.length+1).padStart(3,'0'),client:db.clients[0]?.name||'',issued:today(),due:offset(14),notes:'Thank you for your business!',status:'Draft',tax:+db.settings.tax,items:[{description:'Design services',qty:1,rate:0}]};return heading('Create Invoice','Build and save professional invoices for your clients.',`<div class="row-actions"><button data-action="save-invoice">Save Draft</button><button class="primary" data-action="print-invoice">${icon('download')}Download PDF</button></div>`)+`<div class="invoice-layout"><section class="panel invoice-editor"><div class="panel-head"><h2>Invoice Details</h2><button data-go="bills">Back to Bills</button></div><div class="form-grid">${field('Client',`<input data-invoice="client" list="client-names" value="${esc(invoice.client)}"><datalist id="client-names">${db.clients.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist>`)}${field('Invoice Number',`<input data-invoice="number" value="${esc(invoice.number)}">`)}${field('Issue Date',`<input type="date" data-invoice="issued" value="${invoice.issued}">`)}${field('Due Date',`<input type="date" data-invoice="due" value="${invoice.due}">`)}${field('Notes to Client',`<textarea data-invoice="notes">${esc(invoice.notes)}</textarea>`,'full')}${field('Tax (%)',`<input type="number" min="0" max="100" step="0.1" data-invoice="tax" value="${invoice.tax}">`)}</div><div class="panel-head"><h2>Invoice Items</h2><button data-action="add-invoice-item">${icon('plus')}Add Item</button></div><div class="invoice-item section-note"><span>Description</span><span>Qty</span><span>Rate</span></div><div id="invoice-items">${invoice.items.map((x,i)=>`<div class="invoice-item"><input aria-label="Item ${i+1} description" data-item="${i}:description" value="${esc(x.description)}"><input aria-label="Item ${i+1} quantity" type="number" min="0" step=".01" data-item="${i}:qty" value="${x.qty}"><input aria-label="Item ${i+1} rate" type="number" min="0" step=".01" data-item="${i}:rate" value="${x.rate}"><button data-remove-item="${i}" aria-label="Remove item ${i+1}">${icon('trash')}</button></div>`).join('')}</div><p class="section-note">Download PDF opens your browser’s print dialog. Choose “Save as PDF” for a clean invoice.</p></section><section id="invoice-paper" class="paper">${invoicePaper()}</section></div>`}
function invoicePaper(){const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:invoice.currency||db.settings.currency}).format(v||0);const subtotal=invoice.items.reduce((s,x)=>s+ +x.qty* +x.rate,0);return `<div class="paper-head"><div style="display:flex;gap:12px;align-items:center"><span class="logo">◕</span><div><h2>${esc(db.settings.brand)}</h2></div></div><h2 style="font-size:24px;color:#60636b">INVOICE</h2></div><div class="grid equal" style="margin-top:24px"><div><b>${esc(db.settings.studio)}</b><p>${esc(db.settings.address)}<br>${esc(db.settings.email)}</p></div><div style="text-align:right"><p>Invoice No: &nbsp; ${esc(invoice.number)}<br>Issue Date: &nbsp; ${date(invoice.issued)}<br>Due Date: &nbsp; ${date(invoice.due)}</p></div></div><h3>Bill To</h3><b>${esc(invoice.client)}</b><p>${esc(db.clients.find(c=>c.name===invoice.client)?.email||'')}</p><table><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${invoice.items.map(x=>`<tr><td>${esc(x.description)}</td><td>${x.qty}</td><td>${money(x.rate)}</td><td>${money(x.qty*x.rate)}</td></tr>`).join('')}</tbody></table><div class="paper-total"><span>Subtotal</span><b>${money(subtotal)}</b><span>Tax (${invoice.tax}%)</span><b>${money(subtotal*invoice.tax/100)}</b><strong>Total</strong><strong>${money(totalInvoice(invoice))}</strong></div><div class="signature">${esc(db.settings.brand)}</div><p>${esc(invoice.notes||'Thank you for your business!')}</p>`}
function insights(){let target=+db.settings.target||1,pct=Math.min(100,Math.round(revenue()/target*100)),overdue=db.tasks.filter(t=>t.due<today()&&t.status!=='Done');return hero('Insights','Studio intelligence, targets, and a clearer next step.',`<button data-action="export">${icon('copy')}Export Studio JSON</button>`)+`<div class="stats">${stat('Total Revenue',money(revenue()),'chart','green')}${stat('Total Expenses',money(expenses()),'finance','red')}${stat('Net Profit',money(revenue()-expenses()),'trend','green')}${stat('Active Projects',db.projects.filter(p=>['In Progress','In Review','Planning'].includes(p.status)).length,'layers','blue')}</div><div class="grid three">${panel('Latest Business Brief','bills',`<div class="health-banner"><b>Studio cashflow: <strong>${revenue()>=expenses()?'Positive':'Needs attention'}</strong></b><p>Your recorded revenue is ${money(revenue())}, with ${money(expenses())} in expenses. ${db.tasks.filter(t=>t.status!=='Done').length} tasks are still open across the studio.</p></div><div class="mini-stats"><div><strong>${db.projects.length}</strong><small>Projects</small></div><div><strong>${overdue.length}</strong><small>Overdue tasks</small></div><div><strong>${db.clients.length}</strong><small>Clients</small></div></div><p class="section-note">This brief is calculated from your saved records. It is not AI-generated or a financial forecast.</p>`)}${panel('Revenue Target','trend',`<div class="bill-total">${money(revenue())}</div><p class="muted">of ${money(target)} workspace target</p><div class="progress budget-bar"><span style="width:${pct}%"></span></div><div class="toolbar"><b>${pct}% achieved</b><span class="muted">${money(Math.max(0,target-revenue()))} remaining</span></div><button data-go="settings">Edit Target</button>`)}${panel('Priority Actions','tasks',`<div class="row"><span class="tile red">${icon('clock')}</span><div class="row-main"><b>Review ${overdue.length} overdue tasks</b><small>Unblock delivery and confirm dates.</small></div><button class="iconbtn" data-go="tasks" aria-label="Open tasks">${icon('chevron')}</button></div><div class="row"><span class="tile">${icon('bills')}</span><div class="row-main"><b>Follow up on ${money(outstanding())}</b><small>Outstanding sent and overdue invoices.</small></div><button class="iconbtn" data-go="bills" aria-label="Open bills">${icon('chevron')}</button></div><div class="row"><span class="tile blue">${icon('layers')}</span><div class="row-main"><b>Review recurring tools</b><small>${db.subscriptions.length} subscriptions in your stack.</small></div><button class="iconbtn" data-go="subscriptions" aria-label="Open subscriptions">${icon('chevron')}</button></div>`)}</div><div class="grid equal">${panel('Performance Trends','chart',chart())}${panel('Studio Pulse','star',health())}</div>`}
function users(){return hero('Your Team','The people behind the work.',addBtn('users','Add Member'))+`<div class="panel" style="margin-top:18px"><div class="panel-head"><h2>Team & Roles</h2><span class="badge">Profiles</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${db.users.map((u,i)=>`<tr><td><div class="project-name">${avatar(u.name,i)}${esc(u.name)}</div></td><td>${esc(u.email)}</td><td>${badge(u.role)}</td><td>${badge(u.status)}</td><td><button class="iconbtn" data-edit="users:${u.id}" aria-label="Edit ${esc(u.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div><p class="section-note">Manage profile details here. Enable individual account access in Team logins below.</p></div>`}
function settings(){return hero('Settings','Branding, workspace preferences, and data controls.')+`<div class="tabs settings-tabs">${['Branding','Workspace','Integrations','Data'].map(t=>`<button data-settings-tab="${t}" class="${settingsTab===t?'selected':''}">${t}</button>`).join('')}</div>${settingsTab==='Branding'?`<div class="grid equal">${panel('Branding & Identity','star',`<div class="settings-brand"><span class="logo">◕</span><div><h3>${esc(db.settings.brand)}</h3><p>Strategic design for modern brands.</p>${badge('Default')}</div></div><form id="settings-form">${field('Primary Brand',`<input name="brand" value="${esc(db.settings.brand)}" required>`)}${field('Secondary Brand',`<input name="secondary" value="${esc(db.settings.secondary)}" required>`)}${field('Brand Email',`<input name="email" type="email" value="${esc(db.settings.email)}" required>`)}${field('Website',`<input name="website" value="${esc(db.settings.website)}">`)}<button class="primary">Save Branding</button></form>`)}${panel('Invoice Settings','bills',`<form id="invoice-settings"><div class="form-grid">${field('Studio Name',`<input name="studio" value="${esc(db.settings.studio)}" required>`)}${field('Invoice Prefix',`<input name="prefix" value="${esc(db.settings.prefix)}" required>`)}${field('Address',`<textarea name="address">${esc(db.settings.address)}</textarea>`,'full')}${field('Default Tax (%)',`<input name="tax" type="number" min="0" max="100" step=".1" value="${db.settings.tax}">`)}</div><button class="primary">Save Invoice Settings</button></form>` )}</div>`:settingsTab==='Workspace'?panel('Workspace Preferences','settings',`<form id="settings-form"><div class="form-grid">${field('Your Name',`<input name="owner" value="${esc(db.settings.owner)}" required>`)}${field('Display Currency',`<select name="currency">${options(['USD','LKR'],db.settings.currency)}</select>`)}${field('USD → LKR rate (subscriptions)',`<input type="number" min="1" step=".01" name="fx" value="${db.settings.fx}" required>`)}${field('Workspace Revenue Target',`<input type="number" min="1" name="target" value="${db.settings.target}" required>`)}</div><p class="section-note">Display currency changes labels, not stored amounts. FX conversion applies only to USD subscriptions.</p><button class="primary">Save Preferences</button></form>`):settingsTab==='Integrations'?panel('Connected Workflow','link',`<p class="section-note">External account connections require a hosted backend and OAuth setup. Use the available file-based workflows below.</p>${[['Google Calendar','Export saved meetings as an .ics calendar file.','calendar','Export Calendar'],['ChatGPT','Import structured meeting notes and action items.','meeting-import','Import Notes'],['Spreadsheet','Download income and expense records as CSV.','export-transactions','Export CSV'],['Workspace backup','Portable JSON for moving between browsers.','export','Export Backup']].map(x=>`<div class="integration"><span class="tile">${icon('link')}</span><div class="row-main"><b>${x[0]}</b><small>${x[1]}</small></div><button data-action="${x[2]}">${x[3]}</button></div>`).join('')}`):panel('Your Data','finance',`<p class="section-note">Signed-out work is saved on this device. Signed-in team work syncs to your shared workspace. Export a backup regularly. Importing a backup replaces the current workspace after confirmation.</p><div class="toolbar" style="justify-content:start"><button class="primary" data-action="export">${icon('download')}Export Backup</button><button data-action="import">${icon('upload')}Import Backup</button></div><hr style="border:0;border-top:1px solid #30372f;margin:25px 0"><h3>Start your real workspace</h3><p class="section-note">Remove the sample records and keep your studio settings.</p><button class="danger" data-action="clear-demo">Clear Sample Data</button><button style="margin-left:8px" data-action="reset-demo">Restore Demo</button>`)}<div class="grid equal">${panel('Team & Roles','users',db.users.map((u,i)=>`<div class="row">${avatar(u.name,i)}<div class="row-main"><b>${esc(u.name)}</b><small>${esc(u.email)}</small></div>${badge(u.role)}</div>`).join(''),navbutton('Manage Team','users'))}${panel('Secondary Brand','layers',`<div class="hero" style="margin:0;min-height:150px"><div><h2>${esc(db.settings.secondary)}</h2><p>Visual storytelling for ambitious teams.</p></div></div>`)}</div>`}
function baseRender(){if(![...pages.map(p=>p.toLowerCase()),'invoice'].includes(page))page='home';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">◕</span><div><b>${esc(db.settings.brand)}</b><small>Studio OS</small></div></div><nav aria-label="Main navigation">${pages.map(p=>`<button data-go="${p.toLowerCase()}" class="${page===p.toLowerCase()||page==='invoice'&&p==='Bills'?'active':''}">${icon(p.toLowerCase())}${p}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="primary" data-action="export">Back Up Workspace ${icon('download')}</button></div></aside><main class="workspace"><header class="topbar"><button class="mobile-menu iconbtn" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="searchbox global-search">${icon('search')}<input id="global-search" aria-label="Search workspace" placeholder="Search workspace…"><kbd>⌘ K</kbd><div class="search-results" id="search-results" hidden></div></div><div class="topright"><span class="date">${date(today())}</span><button class="iconbtn" data-action="notifications" aria-label="Notifications">${icon('bell')}</button><div class="profile">${avatar(db.settings.owner)}<div><b>${esc(db.settings.owner)}</b><small>Studio Owner</small></div></div></div></header><div id="page">${({home,projects,tasks,clients,meetings,subscriptions,finance,bills,invoice:invoiceEditor,insights,users,settings}[page])()}</div></main></div>`;bind();}
function options(values,current){return values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function field(label,input,cls=''){return `<label class="field ${cls}">${label}${input}</label>`}
const input=(name,value='',type='text',required=true,extra='')=>`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}>`;
const select=(name,values,value)=>`<select name="${name}">${options(values,value)}</select>`;
function projectSelect(current){return `<select name="project"><option value="">Studio / General</option>${db.projects.map(p=>`<option value="${p.id}" ${p.id===current?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`}
function modal(title,content,sub=''){const d=$('#modal');d.innerHTML=`<div class="dialog-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="iconbtn" data-close aria-label="Close dialog">${icon('close')}</button></div>${content}`;d.querySelector('[data-close]').onclick=()=>d.close();if(!d.open)d.showModal();}
function edit(kind,recordId,status){const existing=db[kind]?.find(x=>x.id===recordId),x=existing||{},isEdit=!!existing;let fields='';if(kind==='projects')fields=field('Project Name',input('name',x.name))+field('Client',input('client',x.client))+field('Status',select('status',['Planning','In Progress','In Review','On Hold','Delivered','Portfolio Queue','Archived'],x.status||'Planning'))+field('Due Date',input('due',x.due||offset(14),'date'))+field('Budget',input('budget',x.budget||0,'number',true,'min="0" step=".01"'))+field('Owner',input('owner',x.owner||db.settings.owner.split(' ')[0]))+field('Description',`<textarea name="description">${esc(x.description)}</textarea>`,'full');
if(kind==='tasks')fields=field('Task Title',input('title',x.title),'full')+field('Project',projectSelect(x.project))+field('Status',select('status',['Backlog','In Progress','Review','Done'],x.status||status||'Backlog'))+field('Priority',select('priority',['Low','Medium','High'],x.priority||'Medium'))+field('Due Date',input('due',x.due||offset(3),'date'))+field('Assignee',input('assignee',x.assignee||db.settings.owner.split(' ')[0]))+field('Description',`<textarea name="description">${esc(x.description)}</textarea>`,'full');
if(kind==='clients')fields=field('Company Name',input('name',x.name))+field('Primary Contact',input('contact',x.contact))+field('Email',input('email',x.email,'email'))+field('Phone',input('phone',x.phone,'tel',false))+field('Website',input('website',x.website,'text',false))+field('Industry',input('industry',x.industry,'text',false))+field('Status',select('status',['Active','Inactive','Blacklisted'],x.status||'Active'))+field('Location',input('location',x.location||'Colombo, Sri Lanka','text',false))+field('Notes',`<textarea name="notes">${esc(x.notes)}</textarea>`,'full');
if(kind==='subscriptions')fields=field('Tool / Service',input('name',x.name))+field('Website',input('website',x.website,'text',false))+field('Monthly Cost (USD)',input('amount',x.amount||0,'number',true,'min="0" step=".01"'))+field('Renewal Date',input('renewal',x.renewal||offset(30),'date'))+field('Reminder (days before)',input('reminder',x.reminder??3,'number',true,'min="0" max="30"'))+field('Status',select('status',['Active','Paused'],x.status||'Active'))+field('Auto-Renew',select('auto',['On','Off'],x.auto===false?'Off':'On'));
if(kind==='transactions')fields=field('Description',input('title',x.title),'full')+field('Amount',input('amount',x.amount||0,'number',true,'min=".01" step=".01"'))+field('Type',select('type',['Income','Expense'],x.type||'Income'))+field('Date',input('date',x.date||today(),'date'))+field('Category',input('category',x.category||'Projects'));
if(kind==='users')fields=field('Full Name',input('name',x.name))+field('Email',input('email',x.email,'email'))+field('Role',select('role',['Founder','Manager','Member'],x.role||'Member'))+field('Status',select('status',['Active','Inactive'],x.status||'Active'));
if(kind==='meetings')fields=field('Meeting Title',input('title',x.title),'full')+field('Project',projectSelect(x.project))+field('Type',select('type',['Team','Client','Internal'],x.type||'Team'))+field('Date',input('date',x.date||today(),'date'))+field('Time',input('time',x.time||'10:00','time'))+field('Attendees',input('attendees',x.attendees||db.settings.owner,'text',false),'full')+field('Summary / Notes',`<textarea name="summary">${esc(x.summary)}</textarea>`,'full');
const singular={projects:'Project',tasks:'Task',clients:'Client',subscriptions:'Subscription',transactions:'Transaction',users:'Team Member',meetings:'Meeting'}[kind];modal(`${isEdit?'Edit':'New'} ${singular}`,`<form id="record-form"><div class="form-grid">${fields}</div><div class="dialog-actions">${isEdit?`<button type="button" class="danger" id="delete-record">${icon('trash')}Delete</button>`:''}<button class="primary" type="submit">${icon('check')}Save ${singular}</button></div></form>`);
$('#record-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const k of ['progress','budget','amount','reminder'])if(k in values)values[k]=Number(values[k]);if('auto'in values)values.auto=values.auto==='On';if(kind==='clients'&&db.clients.some(c=>c.id!==x.id&&c.name.trim().toLowerCase()===values.name.trim().toLowerCase())){toast('A client with this company name already exists.');return}const updated={...x,...values,id:x.id||id()};if(typeof extendRecord==='function')extendRecord(kind,updated,e.target);if(kind==='meetings')updated.action_items=x.action_items||[];if(kind==='clients'&&existing&&existing.name!==values.name){db.projects.forEach(p=>{if(p.client===existing.name)p.client=values.name});db.invoices.forEach(i=>{if(i.client===existing.name)i.client=values.name})}if(isEdit)db[kind]=db[kind].map(v=>v.id===x.id?updated:v);else db[kind].unshift(updated);save(`${singular} ${isEdit?'updated':'created'}: ${values.name||values.title}`);$('#modal').close();render()};if(isEdit)$('#delete-record').onclick=()=>{modal('Delete '+singular+'?',`<p class="section-note">This removes “${esc(x.name||x.title)}” from this workspace. Linked records will remain.</p><div class="dialog-actions"><button id="confirm-delete" class="danger">Delete ${singular}</button></div>`);$('#confirm-delete').onclick=()=>{db[kind]=db[kind].filter(v=>v.id!==x.id);if(kind==='projects'){db.tasks.forEach(t=>{if(t.project===x.id)t.project=''});db.meetings.forEach(m=>{if(m.project===x.id)m.project=''})}save(singular+' deleted');$('#modal').close();render()}}}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function saveInvoice(){if(!invoice.client.trim()||!invoice.number.trim()||!invoice.issued||!invoice.due){toast('Add a client, invoice number, and dates.');return false}if(db.invoices.some(i=>i.id!==invoice.id&&i.number===invoice.number)){toast('Invoice number already exists. Choose a unique number.');return false}if(!invoice.items.length||invoice.items.some(x=>!x.description.trim()||!Number.isFinite(x.qty)||!Number.isFinite(x.rate)||!Number.isFinite(x.qty*x.rate)||x.qty<=0||x.rate<0)||!Number.isFinite(invoice.tax)||!Number.isFinite(totalInvoice(invoice))||invoice.tax<0||invoice.tax>100){toast('Add valid invoice items and a tax rate from 0 to 100.');return false}invoice.currency=invoice.currency||db.settings.currency;const exists=db.invoices.some(i=>i.id===invoice.id);if(exists)db.invoices=db.invoices.map(i=>i.id===invoice.id?structuredClone(invoice):i);else db.invoices.unshift(structuredClone(invoice));save('Invoice saved: '+invoice.number);return true}
function parseMeeting(){try{const m=JSON.parse($('#meeting-json').value);if(m.type!=='chakra-meeting.v1'||typeof m.title!=='string'||!m.title.trim()||typeof m.date!=='string'||isNaN(new Date(m.date)))throw Error('Use chakra-meeting.v1 with a title and valid ISO date.');if(!Array.isArray(m.action_items)||m.action_items.some(a=>typeof a.task!=='string'||!a.task.trim()||typeof a.due_date!=='string'||isNaN(new Date(a.due_date))))throw Error('Action items need a task and valid due_date.');if(m.attendees&&!Array.isArray(m.attendees))throw Error('Attendees must be an array.');parsedMeeting=m;$('#meeting-preview').innerHTML=`<div class="health-banner"><b>${esc(m.title)}</b><p>${date(m.date)} · ${esc(m.date.slice(11,16)||'10:00')}</p></div><p class="section-note">${esc(m.summary||'No summary')}</p><h3 style="font-size:13px">Action Items (${m.action_items.length})</h3>${m.action_items.map(a=>`<div class="row"><span class="tile">${icon('tasks')}</span><div class="row-main"><b>${esc(a.task)}</b><small>${esc(a.assignee||'Unassigned')} · ${date(a.due_date)}</small></div></div>`).join('')}<button class="primary wide" id="save-parsed" style="margin-top:20px">Save Meeting & Create ${m.action_items.length} Tasks</button>`;$('#save-parsed').onclick=()=>{const project=db.projects.find(p=>p.name===m.project)?.id||'';db.meetings.unshift({id:id(),title:m.title,project,date:m.date.slice(0,10),time:m.date.slice(11,16)||'10:00',type:'Client',summary:String(m.summary||''),attendees:(m.attendees||[]).map(a=>typeof a==='string'?a:a.name||'').join(', '),action_items:m.action_items});for(const a of m.action_items)db.tasks.unshift({id:id(),title:a.task,project,status:'Backlog',priority:'Medium',progress:0,due:a.due_date.slice(0,10),assignee:String(a.assignee||db.settings.owner.split(' ')[0]),description:String(m.summary||'')});parsedMeeting=null;save('Meeting imported and action tasks created');meetingTab='Upcoming';render()}}catch(e){parsedMeeting=null;$('#meeting-preview').innerHTML=`<div class="empty danger">${esc(e.message)}</div>`}}
function exportCalendar(){const clean=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),stamp=s=>s.replace(/[-:]/g,'');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Chakra//Studio OS//EN','CALSCALE:GREGORIAN'];for(const m of db.meetings){const d=new Date(m.date+'T'+m.time+':00'),end=new Date(d.getTime()+3600000),local=x=>x.getFullYear()+String(x.getMonth()+1).padStart(2,'0')+String(x.getDate()).padStart(2,'0')+'T'+String(x.getHours()).padStart(2,'0')+String(x.getMinutes()).padStart(2,'0')+'00';lines.push('BEGIN:VEVENT','UID:'+m.id+'@chakra.studio','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z'),'DTSTART:'+stamp(m.date+'T'+m.time+'00'),'DTEND:'+local(end),'SUMMARY:'+clean(m.title),'DESCRIPTION:'+clean(m.summary),'END:VEVENT')}lines.push('END:VCALENDAR');download('chakra-meetings.ics',lines.join('\r\n'),'text/calendar');toast('Calendar exported. Import it into your calendar app.')}
function action(a){if(a==='menu')$('.sidebar').classList.toggle('open');if(a==='export')download('chakra-backup-'+today()+'.json',JSON.stringify(db,null,2));if(a==='import')$('#import-file').click();if(a==='notifications'){const old=$('.notification-menu');if(old){old.remove();return}const div=document.createElement('div');div.className='notification-menu';div.innerHTML=`<strong>Workspace Reminders</strong><p>${db.tasks.filter(t=>t.due<=today()&&t.status!=='Done').length} unfinished tasks due today or earlier.</p><p>${db.subscriptions.filter(s=>s.status==='Active'&&s.renewal<=offset(s.reminder)&&s.renewal>=today()).length} subscription renewal reminders.</p><p class="section-note">Checked when you open the app.</p>`;$('.topbar').append(div)}if(a==='calendar')exportCalendar();if(a==='meeting-import'){meetingTab='Import';go('meetings')}if(a==='parse-meeting')parseMeeting();if(a==='format-guide')modal('Meeting Import Format',`<p class="section-note">Ask ChatGPT for JSON using this structure. Use ISO dates. Project names match existing projects; unmatched names are saved under Studio / General.</p><pre class="code" style="padding:15px;overflow:auto">${esc(JSON.stringify(meetingExample(),null,2))}</pre>`);if(a==='new-invoice'){invoice={id:id(),number:db.settings.prefix+new Date().getFullYear()+'-'+String(db.invoices.length+1).padStart(3,'0'),client:db.clients[0]?.name||'',project:'',issued:today(),due:offset(14),notes:'Thank you for your business!',status:'Draft',tax:+db.settings.tax,items:[{description:'Design services',qty:1,rate:0}]};go('invoice')}if(a==='save-invoice')saveInvoice();if(a==='print-invoice'){if(saveInvoice())window.print()}if(a==='add-invoice-item'){invoice.items.push({description:'',qty:1,rate:0});render()}if(a==='export-transactions'){const cell=s=>'"'+String(s).replace(/"/g,'""')+'"';download('chakra-transactions.csv',[['Description','Type','Category','Date','Amount','Currency'],...db.transactions.map(t=>[t.title,t.type,t.category,t.date,t.amount,db.settings.currency])].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv')}if(a==='clear-demo'||a==='reset-demo'){modal(a==='clear-demo'?'Clear workspace records?':'Restore sample workspace?',`<p class="section-note">This replaces your current records. Export a backup first if you want to keep them.</p><div class="dialog-actions"><button id="export-before-reset">Export Backup</button><button id="confirm-reset" class="danger">${a==='clear-demo'?'Clear Records':'Restore Demo'}</button></div>`);$('#export-before-reset').onclick=()=>action('export');$('#confirm-reset').onclick=()=>{let settings={...db.settings};db=structuredClone(seed);if(a==='clear-demo')for(const k of ['projects','tasks','clients','subscriptions','meetings','transactions','invoices','activity'])db[k]=[];db.settings=settings;save('Workspace '+(a==='clear-demo'?'cleared':'restored'));$('#modal').close();render()}}}
function bind(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-add]').forEach(b=>b.onclick=()=>edit(b.dataset.add,null,b.dataset.status));$$('[data-edit]').forEach(b=>b.onclick=()=>edit(...b.dataset.edit.split(':')));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$$('[data-client]').forEach(b=>b.onclick=()=>{clientSelected=b.dataset.client;render()});$$('[data-meeting-tab]').forEach(b=>b.onclick=()=>{meetingTab=b.dataset.meetingTab;render()});$$('[data-settings-tab]').forEach(b=>b.onclick=()=>{settingsTab=b.dataset.settingsTab;render()});$$('[data-toggle-sub]').forEach(b=>b.onclick=()=>{const s=db.subscriptions.find(x=>x.id===b.dataset.toggleSub);s.auto=!s.auto;save('Auto-renew tracking updated');render()});$$('[data-task-status]').forEach(b=>b.onchange=()=>moveTask(b.dataset.taskStatus,b.value));$$('[data-task]').forEach(b=>b.ondragstart=e=>{e.dataTransfer.setData('text/plain',b.dataset.task);e.dataTransfer.effectAllowed='move'});$$('[data-drop]').forEach(b=>{b.ondragover=e=>{e.preventDefault();b.classList.add('dragover')};b.ondragleave=()=>b.classList.remove('dragover');b.ondrop=e=>{e.preventDefault();moveTask(e.dataTransfer.getData('text/plain'),b.dataset.drop)}});$$('[data-open-invoice]').forEach(b=>b.onclick=()=>{invoice=structuredClone(db.invoices.find(i=>i.id===b.dataset.openInvoice));go('invoice')});$$('[data-invoice-status]').forEach(b=>b.onchange=()=>{db.invoices.find(i=>i.id===b.dataset.invoiceStatus).status=b.value;save('Invoice status updated');render()});$$('[data-invoice]').forEach(b=>b.oninput=()=>{invoice[b.dataset.invoice]=b.dataset.invoice==='tax'?+b.value:b.value;$('#invoice-paper').innerHTML=invoicePaper()});$$('[data-item]').forEach(b=>b.oninput=()=>{let [i,k]=b.dataset.item.split(':');invoice.items[+i][k]=k==='description'?b.value:+b.value;$('#invoice-paper').innerHTML=invoicePaper()});$$('[data-remove-item]').forEach(b=>b.onclick=()=>{invoice.items.splice(+b.dataset.removeItem,1);render()});if($('#page-search'))$('#page-search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#page-search').focus();$('#page-search').setSelectionRange(pos,pos)};if($('#status-filter'))$('#status-filter').onchange=e=>{filter=e.target.value;render()};if($('#finance-period'))$('#finance-period').onchange=e=>{financePeriod=e.target.value;render()};if($('#project-sort'))$('#project-sort').onchange=e=>{let list=[...db.projects].filter(p=>(filter==='All'||filter==='Active'&&!['Delivered','Archived','Portfolio Queue','On Hold'].includes(p.status)||p.status===filter)&&(!query||(p.name+' '+p.client).toLowerCase().includes(query.toLowerCase())));if(e.target.value==='date')list.sort((a,b)=>a.due.localeCompare(b.due));if(e.target.value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));$('#project-rows').innerHTML=projectRows(list);$$('#project-rows [data-edit]').forEach(b=>b.onclick=()=>edit(...b.dataset.edit.split(':')))};for(const f of ['settings-form','invoice-settings'])if($('#'+f))$('#'+f).onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));for(const k of ['tax','fx','target'])if(k in v)v[k]=+v[k];db.settings={...db.settings,...v};save('Workspace settings saved');render()};$('#global-search').oninput=e=>{const q=e.target.value.trim().toLowerCase(),box=$('#search-results');if(!q){box.hidden=true;return}const results=['projects','tasks','clients','meetings'].flatMap(k=>db[k].filter(x=>(x.name||x.title).toLowerCase().includes(q)).map(x=>({kind:k,x}))).slice(0,8);box.hidden=false;box.innerHTML=results.map(r=>`<button data-result="${r.kind}:${r.x.id}"><span>${esc(r.x.name||r.x.title)}</span><small class="muted">${r.kind}</small></button>`).join('')||'<p class="section-note">No matching records</p>';$$('[data-result]').forEach(b=>b.onclick=()=>{box.hidden=true;edit(...b.dataset.result.split(':'))})};}
function moveTask(taskId,status){const t=db.tasks.find(t=>t.id===taskId);if(!t)return;t.status=status;if(status==='Done'){t.progress=100;if(t.checklist)t.checklist=t.checklist.map(c=>({...c,done:true}));}save('Task moved to '+status);render()}
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const incoming=JSON.parse(await file.text());if(!validDB(incoming))throw Error('Not a valid Chakra Studio OS backup.');modal('Replace this workspace?',`<p class="section-note">Import ${incoming.projects.length} projects, ${incoming.tasks.length} tasks, and ${incoming.clients.length} clients from ${esc(file.name)}? This replaces your current records.</p><div class="dialog-actions"><button id="backup-first">Export Current</button><button class="primary" id="confirm-import">Import Backup</button></div>`);$('#backup-first').onclick=()=>action('export');$('#confirm-import').onclick=()=>{db=incoming;save('Workspace backup imported');$('#modal').close();invoice=structuredClone(db.invoices[0]);render()}}catch(err){toast('Import failed: '+err.message)}e.target.value=''};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#global-search').focus()}if(e.key==='Escape'){$('.sidebar')?.classList.remove('open');$('.notification-menu')?.remove();if($('#search-results'))$('#search-results').hidden=true}});document.addEventListener('click',e=>{if(!e.target.closest('.global-search')&&$('#search-results'))$('#search-results').hidden=true});
